// 4. 多数据源路由
public class TenantDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        return TenantContext.getTenantId();
    }
}

// 5. 配额管理
@Service
public class QuotaService {
    @Autowired
    private TenantConfigMapper configMapper;

    public void checkQuota(String tenantId, QuotaType type) {
        TenantConfig config = configMapper.findByTenantId(tenantId);
        switch (type) {
            case API_CALL:
                if (config.getApiCallCount() >= config.getApiCallLimit()) {
                    throw new QuotaExceededException("API调用次数超限");
                }
                break;
            case STORAGE:
                if (config.getStorageUsed() >= config.getStorageLimit()) {
                    throw new QuotaExceededException("存储空间超限");
                }
                break;
            case USER_COUNT:
                if (config.getUserCount() >= config.getUserLimit()) {
                    throw new QuotaExceededException("用户数超限");
                }
                break;
        }
    }
}

// 6. 功能开关
public boolean hasFeature(String tenantId, String feature) {
    TenantConfig config = configMapper.findByTenantId(tenantId);
    return config.getFeatures().contains(feature);
}
